@import url("https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=DM+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap");
/* Brand values and shared design tokens */
:root {
  /* Brand */
  --siq-orange: #FF6600;
  --siq-orange-hover: color-mix(in srgb, var(--siq-orange) 90%, black);
  --siq-blue: #2E7DFF;
  --siq-blue-hover: color-mix(in srgb, var(--siq-blue) 80%, black);
  --siq-cyan: #4CC2FF;
  --siq-logo-blue: #0073E6;
  --siq-orange-light: color-mix(in srgb, var(--siq-orange) 80%, white);
  --siq-orange-bubble: color-mix(in srgb, var(--siq-orange) 82%, white);
  --siq-orange-ink: #25120A;

  /* Ground — black */
  --siq-bg: #0A0B10;
  --siq-bg-elevated: #111A2C;
  --siq-bg-surface: #16233C;
  --siq-border: rgba(255,255,255,0.09);
  --siq-border-strong: rgba(255,255,255,0.16);

  --siq-text-primary: #F6F8FC;
  --siq-text-secondary: #C3CEDF;
  --siq-text-muted: #8494AE;

  /* Ivory — conversion surfaces (drive-leads bands) */
  --siq-ivory: #F4F0E7;
  --siq-ivory-ground: #EAE0CD;
  --siq-ink: #12203A;
  --siq-ink-body: #41506A;
  --siq-ink-line: rgba(18,32,58,0.16);

  /* Severity */
  --siq-success: #22C55E;
  --siq-caution: #FBBF24;
  --siq-danger: #F0603A;

  /* Type */
  --font-sans: "DM Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-serif: "Fraunces", Georgia, "Times New Roman", serif;
  --font-mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, monospace;

  --fs-xs: 0.75rem;  --fs-sm: 0.875rem; --fs-base: 1rem;  --fs-md: 1.125rem;
  --fs-lg: 1.25rem;  --fs-xl: 1.5rem;   --fs-2xl: 2rem;   --fs-3xl: 2.6rem;
  --fs-4xl: 3.5rem;  --fs-5xl: 4.6rem;

  --sp-1:0.25rem; --sp-2:0.5rem; --sp-3:0.75rem; --sp-4:1rem; --sp-6:1.5rem;
  --sp-8:2rem; --sp-12:3rem; --sp-16:4rem; --sp-24:6rem;

  --container-max: 1200px;
  --radius: 0;
  --transition: 200ms ease;
}
body[data-page] { margin: 0; }
/* Shared marketing styles */
/* =========================================================
   SCALIENT IQ — Marketing Website Design System
   SiQ 2026 · Luminous Editorial (black) — Aug 30, 2026
   Same class names as prior system; new visual language.
   ========================================================= */





:where(body[data-site-core]) * { margin:0; padding:0; box-sizing:border-box; }
html:where(:has(body[data-site-core])) { scroll-behavior:smooth; }
body:where([data-site-core]) {
  font-family: var(--font-sans);
  background: var(--siq-bg);
  color: var(--siq-text-primary);
  line-height: 1.6;
  font-size: var(--fs-base);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* ============ LAYOUT ============ */
:where(body[data-site-core]) .container, body:where([data-site-core]).container { max-width: var(--container-max); margin:0 auto; padding:0 var(--sp-6); }
:where(body[data-site-core]) section { padding: var(--sp-24) 0; position: relative; }
@media (max-width:768px){ :where(body[data-site-core]) section { padding: var(--sp-16) 0; } }

/* ============ TYPOGRAPHY ============ */
:where(body[data-site-core]) h1, :where(body[data-site-core]) h2, :where(body[data-site-core]) h3, :where(body[data-site-core]) h4 {
  font-family: var(--font-serif);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.08;
  color: var(--siq-text-primary);
}
:where(body[data-site-core]) h1 { font-size: var(--fs-5xl); letter-spacing:-0.03em; }
:where(body[data-site-core]) h2 { font-size: var(--fs-3xl); }
:where(body[data-site-core]) h3 { font-size: var(--fs-xl); }
:where(body[data-site-core]) h4 { font-size: var(--fs-lg); }
@media (max-width:768px){ :where(body[data-site-core]) h1 { font-size: var(--fs-3xl); } :where(body[data-site-core]) h2 { font-size: var(--fs-2xl); } }

:where(body[data-site-core]) p { color: var(--siq-text-secondary); }

:where(body[data-site-core]) .eyebrow, body:where([data-site-core]).eyebrow {
  display:inline-block;
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  font-weight: 500;
  text-transform: none;
  letter-spacing: normal;
  color: var(--siq-orange);
  padding: var(--sp-2) var(--sp-4);
  border: 1px solid var(--siq-border);
  background: rgba(255,255,255,0.02);
  margin-bottom: var(--sp-6);
}

:where(body[data-site-core]) .text-orange, body:where([data-site-core]).text-orange { color: var(--siq-orange); }
:where(body[data-site-core]) .text-blue, body:where([data-site-core]).text-blue { color: var(--siq-cyan); }
:where(body[data-site-core]) .text-secondary, body:where([data-site-core]).text-secondary { color: var(--siq-text-secondary); }
:where(body[data-site-core]) .text-muted, body:where([data-site-core]).text-muted { color: var(--siq-text-muted); }

/* ============ NAVIGATION ============ */
:where(body[data-site-core]) .nav, body:where([data-site-core]).nav {
  position: sticky; top:0; z-index:100;
  background: rgba(10,11,16,0.82);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--siq-border);
}
:where(body[data-site-core]) .nav-inner, body:where([data-site-core]).nav-inner {
  display:flex; align-items:center; justify-content:space-between;
  padding: var(--sp-4) var(--sp-6);
  max-width: var(--container-max); margin:0 auto;
}
:where(body[data-site-core]) .logo, body:where([data-site-core]).logo { display:inline-flex; align-items:center; text-decoration:none; color:var(--siq-text-primary);
  font-family: var(--font-serif); font-weight:600; font-size: var(--fs-lg); letter-spacing:-0.01em; }
:where(body[data-site-core]) .logo img, body:where([data-site-core]).logo img { height:30px; width:auto; display:block; }
:where(body[data-site-core]) .logo svg, body:where([data-site-core]).logo svg { height:26px; width:auto; display:block; }
:where(body[data-site-core]) .logo .scalient, body:where([data-site-core]).logo .scalient { color: var(--siq-cyan); }
:where(body[data-site-core]) .logo .iq, body:where([data-site-core]).logo .iq { color: var(--siq-orange); }
:where(body[data-site-core]) .footer-brand .logo img, body:where([data-site-core]).footer-brand .logo img { height:34px; }
:where(body[data-site-core]) .footer-brand .logo svg, body:where([data-site-core]).footer-brand .logo svg { height:30px; }

:where(body[data-site-core]) .nav-links, body:where([data-site-core]).nav-links { display:flex; gap: var(--sp-8); list-style:none; margin-left: var(--sp-12); }
:where(body[data-site-core]) .nav-links a, body:where([data-site-core]).nav-links a {
  color: var(--siq-text-secondary); text-decoration:none;
  font-size: var(--fs-sm); font-weight:500; transition: color var(--transition); white-space:nowrap;
}
:where(body[data-site-core]) .nav-links a:hover, body:where([data-site-core]).nav-links a:hover, :where(body[data-site-core]) .nav-links a.active, body:where([data-site-core]).nav-links a.active { color: var(--siq-text-primary); }
:where(body[data-site-core]) .nav-cta, body:where([data-site-core]).nav-cta { display:flex; gap: var(--sp-3); align-items:center; }
@media (max-width:900px){ :where(body[data-site-core]) .nav-links, body:where([data-site-core]).nav-links { display:none; } }
@media (max-width:600px){
  :where(body[data-site-core]) .nav-inner, body:where([data-site-core]).nav-inner { padding: var(--sp-3) var(--sp-4); }
  :where(body[data-site-core]) .logo img, body:where([data-site-core]).logo img { height:26px; }
  :where(body[data-site-core]) .nav-cta .btn-ghost, body:where([data-site-core]).nav-cta .btn-ghost { display:none; }
  :where(body[data-site-core]) .nav-cta .btn-primary, body:where([data-site-core]).nav-cta .btn-primary { padding: var(--sp-2) var(--sp-4); font-size: var(--fs-xs); box-shadow:none; }
}

/* ============ BUTTONS ============ */
:where(body[data-site-core]) .btn, body:where([data-site-core]).btn {
  display:inline-flex; align-items:center; gap: var(--sp-2);
  padding: var(--sp-3) var(--sp-6);
  font-family: var(--font-sans); font-size: var(--fs-sm); font-weight:600;
  text-transform: none; letter-spacing:0.06em; text-decoration:none;
  border:1px solid transparent; cursor:pointer; transition: all var(--transition); white-space:nowrap;
}
:where(body[data-site-core]) .btn-primary, body:where([data-site-core]).btn-primary { background: var(--siq-orange); color:#FFFFFF; box-shadow: 0 10px 30px -12px color-mix(in srgb, var(--siq-orange) 60%, transparent); }
:where(body[data-site-core]) .btn-primary:hover, body:where([data-site-core]).btn-primary:hover { background: var(--siq-orange-hover); transform: translateY(-1px); }
:where(body[data-site-core]) .btn-secondary, body:where([data-site-core]).btn-secondary { background: transparent; color: var(--siq-text-primary); border-color: var(--siq-border-strong); }
:where(body[data-site-core]) .btn-secondary:hover, body:where([data-site-core]).btn-secondary:hover { border-color: var(--siq-orange); color: var(--siq-orange); }
:where(body[data-site-core]) .btn-ghost, body:where([data-site-core]).btn-ghost { background:transparent; color: var(--siq-text-secondary); }
:where(body[data-site-core]) .btn-ghost:hover, body:where([data-site-core]).btn-ghost:hover { color: var(--siq-orange); }
:where(body[data-site-core]) .btn-lg, body:where([data-site-core]).btn-lg { padding: var(--sp-4) var(--sp-8); font-size: var(--fs-base); }

/* ============ HERO ============ */
:where(body[data-site-core]) .hero, body:where([data-site-core]).hero { padding: var(--sp-24) 0 var(--sp-16); position:relative; overflow:hidden; }
:where(body[data-site-core]) .hero::before, body:where([data-site-core]).hero::before {
  content:none;
}
:where(body[data-site-core]) .hero-inner, body:where([data-site-core]).hero-inner { position:relative; z-index:1; text-align:center; max-width:920px; margin:0 auto; }
:where(body[data-site-core]) .hero h1, body:where([data-site-core]).hero h1 { margin-bottom: var(--sp-6); }
:where(body[data-site-core]) .hero-subhead, body:where([data-site-core]).hero-subhead {
  font-size: var(--fs-md); color: var(--siq-text-secondary);
  margin: 0 auto var(--sp-8); max-width:720px;
}
:where(body[data-site-core]) .hero-cta, body:where([data-site-core]).hero-cta { display:flex; justify-content:center; gap: var(--sp-4); flex-wrap:wrap; }

:where(body[data-site-core]) .hero-quote, body:where([data-site-core]).hero-quote {
  max-width:720px; margin: var(--sp-8) auto; padding: var(--sp-6) var(--sp-8);
  background: var(--siq-bg-elevated);
  border-left: 3px solid var(--siq-orange); text-align:left;
}
:where(body[data-site-core]) .hero-quote p, body:where([data-site-core]).hero-quote p { margin:0 0 var(--sp-3); font-family: var(--font-serif); font-size: var(--fs-lg);
  font-weight:500; line-height:1.4; color: var(--siq-text-primary); }
:where(body[data-site-core]) .hero-quote cite, body:where([data-site-core]).hero-quote cite { display:block; font-family: var(--font-mono); font-size: var(--fs-xs);
  font-style:normal; text-transform:none; letter-spacing:0.12em; color: var(--siq-text-muted); }

/* ============ STAT STRIPS ============ */
:where(body[data-site-core]) .stats, body:where([data-site-core]).stats { display:grid; grid-template-columns:repeat(3,1fr); gap: var(--sp-4); margin-top: var(--sp-16); }
:where(body[data-site-core]) .stat, body:where([data-site-core]).stat {
  background: var(--siq-bg-elevated);
  border:1px solid var(--siq-border); padding: var(--sp-8) var(--sp-6); text-align:center;
  box-shadow: 0 28px 60px -40px rgba(0,0,0,0.9);
}
:where(body[data-site-core]) .stat-value, body:where([data-site-core]).stat-value { font-family: var(--font-serif); font-size: var(--fs-3xl); font-weight:600;
  color: var(--siq-cyan); letter-spacing:-0.02em; margin-bottom: var(--sp-2); }
:where(body[data-site-core]) .stat-label, body:where([data-site-core]).stat-label { font-family: var(--font-mono); font-size: var(--fs-xs); text-transform:none;
  letter-spacing:0.1em; color: var(--siq-text-muted); }
@media (max-width:768px){ :where(body[data-site-core]) .stats, body:where([data-site-core]).stats { grid-template-columns:1fr; } }

/* ============ SECTION HEADER + GRIDS ============ */
:where(body[data-site-core]) .section-header, body:where([data-site-core]).section-header { text-align:center; max-width:820px; margin:0 auto var(--sp-16); }
:where(body[data-site-core]) .section-header h2, body:where([data-site-core]).section-header h2 { margin-bottom: var(--sp-4); }
:where(body[data-site-core]) .grid-3, body:where([data-site-core]).grid-3 { display:grid; grid-template-columns:repeat(3,1fr); gap: var(--sp-6); }
:where(body[data-site-core]) .grid-2, body:where([data-site-core]).grid-2 { display:grid; grid-template-columns:repeat(2,1fr); gap: var(--sp-6); }
@media (max-width:900px){ :where(body[data-site-core]) .grid-3, body:where([data-site-core]).grid-3, :where(body[data-site-core]) .grid-2, body:where([data-site-core]).grid-2 { grid-template-columns:1fr; } }

:where(body[data-site-core]) .card, body:where([data-site-core]).card {
  background: var(--siq-bg-elevated);
  border:1px solid var(--siq-border-strong);
  padding: var(--sp-8);
  box-shadow: 0 30px 66px -42px rgba(0,0,0,0.95);
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
}
:where(body[data-site-core]) .card:hover, body:where([data-site-core]).card:hover { border-color: var(--siq-orange); transform: translateY(-4px);
  box-shadow: 0 40px 80px -40px rgba(0,0,0,0.95); }
:where(body[data-site-core]) .card-icon, body:where([data-site-core]).card-icon {
  width:48px; height:48px; background: color-mix(in srgb, var(--siq-orange) 10%, transparent);
  border:1px solid color-mix(in srgb, var(--siq-orange) 35%, transparent);
  display:flex; align-items:center; justify-content:center; margin-bottom: var(--sp-4);
  color: var(--siq-orange); font-family: var(--font-serif); font-weight:600; font-size: var(--fs-lg);
}
:where(body[data-site-core]) .card h3, body:where([data-site-core]).card h3 { margin-bottom: var(--sp-3); }
:where(body[data-site-core]) .card p, body:where([data-site-core]).card p { font-size: var(--fs-sm); }

/* ============ NUMBERED COMPONENT BLOCK ============ */
:where(body[data-site-core]) .component, body:where([data-site-core]).component {
  display:grid; grid-template-columns:auto 1fr; gap: var(--sp-8);
  padding: var(--sp-12) 0; border-bottom:1px solid var(--siq-border); align-items:start;
}
:where(body[data-site-core]) .component:last-of-type, body:where([data-site-core]).component:last-of-type { border-bottom:none; }
:where(body[data-site-core]) .component-num, body:where([data-site-core]).component-num { font-family: var(--font-serif); font-size: var(--fs-4xl); font-weight:600;
  color: var(--siq-orange); line-height:1; letter-spacing:-0.04em; }
:where(body[data-site-core]) .component-label, body:where([data-site-core]).component-label { font-family: var(--font-mono); font-size: var(--fs-xs); text-transform:none;
  letter-spacing:0.14em; color: var(--siq-text-muted); margin-bottom: var(--sp-2); }
:where(body[data-site-core]) .component h3, body:where([data-site-core]).component h3 { margin-bottom: var(--sp-4); font-size: var(--fs-2xl); }
@media (max-width:768px){ :where(body[data-site-core]) .component, body:where([data-site-core]).component { grid-template-columns:1fr; gap: var(--sp-4); } }

/* ============ CTA BANNER — IVORY (conversion) ============ */
:where(body[data-site-core]) .cta-banner, body:where([data-site-core]).cta-banner {
  background: var(--siq-ivory);
  border: 1px solid var(--siq-ivory-ground);
  padding: var(--sp-16);
  text-align:center;
  box-shadow: 0 40px 90px -50px rgba(0,0,0,0.8);
  position: relative;
}
:where(body[data-site-core]) .cta-banner::before, body:where([data-site-core]).cta-banner::before {
  content:none;
}
:where(body[data-site-core]) .cta-banner > *, body:where([data-site-core]).cta-banner > * { position: relative; }
:where(body[data-site-core]) .cta-banner h2, body:where([data-site-core]).cta-banner h2 { color: var(--siq-ink); margin-bottom: var(--sp-4); }
:where(body[data-site-core]) .cta-banner p, body:where([data-site-core]).cta-banner p { color: var(--siq-ink-body); font-size: var(--fs-md);
  margin: 0 auto var(--sp-8); max-width:700px; }
:where(body[data-site-core]) .cta-banner .eyebrow, body:where([data-site-core]).cta-banner .eyebrow { color: var(--siq-orange); border-color: var(--siq-ink-line); background: color-mix(in srgb, var(--siq-ink) 3%, transparent); }
:where(body[data-site-core]) .cta-banner .btn-secondary, body:where([data-site-core]).cta-banner .btn-secondary { color: var(--siq-ink); border-color: var(--siq-ink-line); }
:where(body[data-site-core]) .cta-banner .btn-secondary:hover, body:where([data-site-core]).cta-banner .btn-secondary:hover { border-color: var(--siq-orange); color: var(--siq-orange); }

/* ============ FAQ ============ */
:where(body[data-site-core]) .faq-list, body:where([data-site-core]).faq-list { max-width:820px; margin:0 auto; }
:where(body[data-site-core]) .faq-item, body:where([data-site-core]).faq-item { border-bottom:1px solid var(--siq-border); }
:where(body[data-site-core]) .faq-question, body:where([data-site-core]).faq-question {
  width:100%; background:transparent; border:none; color: var(--siq-text-primary);
  font-family: var(--font-sans); font-size: var(--fs-md); font-weight:600; text-align:left;
  padding: var(--sp-6) 0; cursor:pointer; display:flex; justify-content:space-between; align-items:center; gap: var(--sp-4);
}
:where(body[data-site-core]) .faq-question:hover, body:where([data-site-core]).faq-question:hover { color: var(--siq-orange); }
:where(body[data-site-core]) .faq-icon, body:where([data-site-core]).faq-icon { color: var(--siq-orange); font-size: var(--fs-xl); transition: transform var(--transition); }
:where(body[data-site-core]) .faq-item[data-open="true"] .faq-icon, body:where([data-site-core]).faq-item[data-open="true"] .faq-icon { transform: rotate(45deg); }
:where(body[data-site-core]) .faq-answer, body:where([data-site-core]).faq-answer { max-height:0; overflow:hidden; transition: max-height var(--transition), padding var(--transition); }
:where(body[data-site-core]) .faq-item[data-open="true"] .faq-answer, body:where([data-site-core]).faq-item[data-open="true"] .faq-answer { max-height:600px; padding-bottom: var(--sp-6); }

/* ============ FOOTER ============ */
:where(body[data-site-core]) footer { background:#080910; border-top:1px solid var(--siq-border); padding: var(--sp-16) 0 var(--sp-8); }
:where(body[data-site-core]) .footer-grid, body:where([data-site-core]).footer-grid { display:grid; grid-template-columns:2fr 1fr 1fr 1fr; gap: var(--sp-8); margin-bottom: var(--sp-12); }
:where(body[data-site-core]) .footer-brand p, body:where([data-site-core]).footer-brand p { font-size: var(--fs-sm); margin-top: var(--sp-4); max-width:320px; }
:where(body[data-site-core]) .footer-col h4, body:where([data-site-core]).footer-col h4 { font-family: var(--font-mono); font-size: var(--fs-xs); text-transform:none;
  letter-spacing:0.14em; color: var(--siq-text-muted); margin-bottom: var(--sp-4); }
:where(body[data-site-core]) .footer-col ul, body:where([data-site-core]).footer-col ul { list-style:none; }
:where(body[data-site-core]) .footer-col li, body:where([data-site-core]).footer-col li { margin-bottom: var(--sp-2); }
:where(body[data-site-core]) .footer-col a, body:where([data-site-core]).footer-col a { color: var(--siq-text-secondary); text-decoration:none; font-size: var(--fs-sm); transition: color var(--transition); }
:where(body[data-site-core]) .footer-col a:hover, body:where([data-site-core]).footer-col a:hover { color: var(--siq-orange); }
:where(body[data-site-core]) .footer-bottom, body:where([data-site-core]).footer-bottom { padding-top: var(--sp-6); border-top:1px solid var(--siq-border);
  display:flex; justify-content:space-between; font-family: var(--font-mono); font-size: var(--fs-xs); color: var(--siq-text-muted); }
@media (max-width:768px){ :where(body[data-site-core]) .footer-grid, body:where([data-site-core]).footer-grid { grid-template-columns:1fr 1fr; } :where(body[data-site-core]) .footer-bottom, body:where([data-site-core]).footer-bottom { flex-direction:column; gap: var(--sp-2); } }

/* ============ FORMS ============ */
