/* Brand-colored signal bubbles */
body[data-page="index"] .bubble-cyan { fill: var(--siq-cyan); }
body[data-page="index"] .bubble-orange { fill: var(--siq-orange-bubble); }

/* Printable copy generated by client intake */
body[data-page="client-intake-print"] { font-family: Arial, Helvetica, sans-serif; color: #0A1628; margin: 36px; line-height: 1.45; }
body[data-page="client-intake-print"] h1 { font-size: 24px; margin: 0 0 2px; }
body[data-page="client-intake-print"] h2 { font-size: 15px; color: var(--siq-logo-blue); margin: 22px 0 8px; border-bottom: 2px solid var(--siq-logo-blue); padding-bottom: 3px; }
body[data-page="client-intake-print"] .sub { color: #666; margin: 0 0 18px; font-size: 13px; }
body[data-page="client-intake-print"] table { border-collapse: collapse; width: 100%; font-size: 13px; margin-bottom: 6px; }
body[data-page="client-intake-print"] td { border: 1px solid #ddd; padding: 6px 9px; vertical-align: top; }
body[data-page="client-intake-print"] td.l { background: #f2f5f8; font-weight: bold; width: 32%; }
body[data-page="client-intake-print"] .np { margin-top: 24px; color: #999; font-size: 12px; }
@media print { body[data-page="client-intake-print"] .np { display: none; } }
